class ProfileScreen extends StatefulWidget {
  static const String routeName = '/profile';

  const ProfileScreen({super.key});

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  @override
  void initState() {
    super.initState();
    final state = context.read<UserBloc>().state;
    if (state is UserInitial || state is UserError) {
      context.read<UserBloc>().add(GetUserProfileEvent());
    }
  }

  @override
  Widget build(BuildContext context) {
    return ZinkoBackground(
      child: Scaffold(
        backgroundColor: Colors.transparent,
        appBar: const ZinkoAppBar(
          title: 'Profile',
          showBackButton: false,
          leading: SizedBox.shrink(),
        ),
        body: SafeArea(
          child: BlocBuilder<UserBloc, UserState>(
            buildWhen: (previous, current) =>
                current is UserLoading ||
                current is UserLoaded ||
                current is UserError,
            builder: (context, state) {
              final user = state is UserLoaded ? state.user : null;
              final isLoading = state is UserLoading;
              final isError = state is UserError;

              return RefreshIndicator(
                onRefresh: () async {
                  context.read<UserBloc>().add(GetUserProfileEvent());
                },
                color: AppColors.primary,
                backgroundColor: GlassTheme.glassColor(context),
                child: SingleChildScrollView(
                  physics: const BouncingScrollPhysics(
                    parent: AlwaysScrollableScrollPhysics(),
                  ),
                  padding: const EdgeInsets.symmetric(horizontal: 20),
                  child: Column(
                    children: [
                      _buildHeader(context, user, isLoading),
                      if (isError) ...[
                        const SizedBox(height: 12),
                        _buildErrorBanner(context, (state).message),
                      ],
                      const SizedBox(height: 12),
                      if (user != null) ...[
                        _buildCompletionCard(context, user),
                        const SizedBox(height: 12),
                      ],
                      _buildMembershipCard(context, user),
                      const SizedBox(height: 12),
                      _buildSectionTitle(context, 'MY ACCOUNT'),
                      const SizedBox(height: 10),
                      _buildAccountCard(context, user),
                      const SizedBox(height: 20),
                      _buildSectionTitle(context, 'RECENT ACTIVITY'),
                      const SizedBox(height: 10),
                      _buildMenuGrid(context),
                      const SizedBox(height: 20),
                      _buildSectionTitle(context, 'PREFERENCES & SETTINGS'),
                      const SizedBox(height: 10),
                      _buildGeneralList(context, user),
                      const SizedBox(height: 24),
                      _buildLogoutBtn(context),
                      const SizedBox(height: 100),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }

  Widget _buildErrorBanner(BuildContext context, String message) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: OptimizedColors.error08,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: OptimizedColors.error25),
      ),
      child: Row(
        children: [
          const Icon(Icons.error_outline_rounded, color: AppColors.error),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              message,
              style: const TextStyle(
                  color: AppColors.error,
                  fontSize: 13,
                  fontWeight: FontWeight.w600),
            ),
          ),
          TextButton(
            onPressed: () =>
                context.read<UserBloc>().add(GetUserProfileEvent()),
            child: const Text('RETRY',
                style: TextStyle(
                    color: AppColors.error, fontWeight: FontWeight.w900)),
          ),
        ],
      ),
    );
  }

  Widget _buildHeader(BuildContext context, dynamic user, bool isLoading) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        const SizedBox(height: 40),
        Hero(
          tag: 'profile_pic',
          child: Container(
            width: 90,
            height: 90,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              border: Border.all(
                  color: OptimizedColors.applyAlpha(AppColors.brightBlue, 0.5), width: 3.5),
              boxShadow: [
                BoxShadow(
                    color: OptimizedColors.applyAlpha(AppColors.brightBlue, 0.2),
                    blurRadius: 20,
                    spreadRadius: 1)
              ],
            ),
            child: ClipOval(
              child: isLoading
                  ? Center(
                      child: CircularProgressIndicator(
                          color: GlassTheme.textColor(context),
                          strokeWidth: 2))
                  : ZinkoNetworkImage(
                      imageUrl: user?.profileImage ?? '',
                      width: 90,
                      height: 90,
                      fit: BoxFit.cover,
                    ),
            ),
          ),
        )
            .animate()
            .scale(curve: Curves.easeOutBack, duration: 300.ms)
            .rotate(begin: -0.05, end: 0),
        const SizedBox(height: 12),
        Text(
          user?.name.toUpperCase() ?? (isLoading ? 'LOADING...' : 'ME'),
          style: TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.w900,
              color: GlassTheme.textColor(context),
              letterSpacing: -0.5),
        ).animate(delay: 200.ms).fadeIn(),
        const SizedBox(height: 4),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
          decoration: BoxDecoration(
            color: GlassTheme.glassColor(context),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: GlassTheme.glassBorder(context)),
          ),
          child: Text(
            'EXPERT USER',
            style: TextStyle(
                fontSize: 9,
                color: GlassTheme.secondaryTextColor(context),
                fontWeight: FontWeight.w900,
                letterSpacing: 1.5),
          ),
        ).animate(delay: 350.ms).fadeIn(),
      ],
    );
  }

  Widget _buildSectionTitle(BuildContext context, String title) {
    return Align(
      alignment: Alignment.centerLeft,
      child: Padding(
        padding: const EdgeInsets.only(left: 4),
        child: Text(
          title,
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w900,
            color: GlassTheme.tertiaryTextColor(context),
            letterSpacing: 1.2,
          ),
        ),
      ),
    );
  }

  Widget _buildAccountCard(BuildContext context, dynamic user) {
    return ZinkoCommonCard(
      padding: EdgeInsets.zero,
      child: Column(
        children: [
          _buildAccountTile(
              context, 'Email', user?.email ?? '--', Icons.email_outlined),
          Divider(
              height: 1,
              color: OptimizedColors.white05),
          _buildAccountTile(context, 'Phone', user?.phone ?? '--',
              Icons.phone_android_rounded),
          Divider(
              height: 1,
              color: OptimizedColors.white05),
          _buildAccountTile(
              context,
              'Bio',
              (user?.bio ?? '').isEmpty ? 'Not specified' : user!.bio,
              Icons.info_outline_rounded),
        ],
      ),
    ).animate().fadeIn(delay: 450.ms);
  }

  Widget _buildAccountTile(
      BuildContext context, String label, String value, IconData icon) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 12.0),
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
                color: OptimizedColors.applyAlpha(GlassTheme.textColor(context), 0.08),
                shape: BoxShape.circle),
            child: Icon(icon,
                color: GlassTheme.secondaryTextColor(context), size: 18),
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(label,
                    style: TextStyle(
                        fontSize: 10,
                        color: GlassTheme.tertiaryTextColor(context),
                        fontWeight: FontWeight.w900,
                        letterSpacing: 0.5)),
                const SizedBox(height: 2),
                Text(value,
                    style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: GlassTheme.textColor(context))),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildMembershipCard(BuildContext context, dynamic user) {
    return ZinkoCommonCard(
      onTap: () {
        if (user != null && !user.isProfileComplete) {
          ZinkoProfileCompletionDialog.show(context, user);
        } else {
          Navigator.pushNamed(context, SubscriptionPlansScreen.routeName);
        }
      },
      backgroundColor: AppColors.royalBlue,
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              gradient: LinearGradient(colors: [
                OptimizedColors.applyAlpha(AppColors.gold, 0.2),
                OptimizedColors.applyAlpha(AppColors.gold, 0.05)
              ]),
              shape: BoxShape.circle,
              border: Border.all(color: OptimizedColors.applyAlpha(AppColors.gold, 0.3)),
            ),
            child: const Icon(Icons.stars_rounded,
                color: AppColors.gold, size: 28),
          ),
          const SizedBox(width: 20),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '${user?.membership.toUpperCase() ?? 'FREE'} MEMBER',
                  style: const TextStyle(
                      color: AppColors.white,
                      fontSize: 18,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 0.5),
                ),
                const SizedBox(height: 2),
                Row(
                  children: [
                    Text(
                      user != null
                          ? 'Premium Benefits Active'
                          : 'Join our premium club',
                      style: TextStyle(
                          color: user != null
                              ? AppColors.success
                              : OptimizedColors.white70,
                          fontSize: 12,
                          fontWeight: FontWeight.w700),
                    ),
                    const SizedBox(width: 4),
                    if (user != null)
                      const Icon(Icons.check_circle,
                          color: AppColors.success, size: 12),
                  ],
                ),
              ],
            ),
          ),
          const Icon(Icons.arrow_forward_ios_rounded,
              color: AppColors.white, size: 14),
        ],
      ),
    ).animate().fadeIn(delay: 300.ms);
  }

  Widget _buildMenuGrid(BuildContext context) {
    return GridView.count(
      shrinkWrap: true,
      // padding: EdgeInsets.zero,
      physics: const NeverScrollableScrollPhysics(),
      crossAxisCount: 2,
      mainAxisSpacing: 10,
      crossAxisSpacing: 10,
      childAspectRatio: 1.8,

      children: [
