import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:zinko_app/features/cafe/domain/usecases/search_cafes.dart';
import 'package:zinko_app/features/cafe/domain/usecases/toggle_wishlist.dart';
import 'package:zinko_app/features/cafe/domain/usecases/get_wishlist.dart';
import 'package:zinko_app/features/cafe/presentation/bloc/cafe_event.dart';
import 'package:zinko_app/features/cafe/presentation/bloc/cafe_state.dart';

class CafeBloc extends Bloc<CafeEvent, CafeState> {
  final SearchCafes searchCafes;
  final ToggleWishlist toggleWishlist;
  final GetWishlist getWishlist;

  CafeBloc({
    required this.searchCafes,
    required this.toggleWishlist,
    required this.getWishlist,
  }) : super(CafeInitial()) {
    on<SearchCafesEvent>(_onSearchCafes);
    on<ToggleWishlistEvent>(_onToggleWishlist);
    on<GetWishlistEvent>(_onGetWishlist);
    on<ResetCafeEvent>(_onResetCafe);
  }

  void _onResetCafe(ResetCafeEvent event, Emitter<CafeState> emit) {
    emit(CafeInitial());
  }

  Future<void> _onGetWishlist(
    GetWishlistEvent event,
    Emitter<CafeState> emit,
  ) async {
    emit(CafeLoading());
    try {
      final wishlist = await getWishlist(event.userCode);
      emit(CafeWishlistLoaded(wishlist: wishlist));
    } catch (e) {
      emit(CafeError(message: e.toString()));
    }
  }

  Future<void> _onToggleWishlist(
    ToggleWishlistEvent event,
    Emitter<CafeState> emit,
  ) async {
    final currentState = state;
    if (currentState is CafeLoaded) {
      // Optimistic UI update
      final updatedCafes = currentState.cafes.map((cafe) {
        if (cafe.cafeId == event.cafeId) {
          return cafe.copyWith(isLiked: !cafe.isLiked);
        }
        return cafe;
      }).toList();

      emit(CafeLoaded(cafes: updatedCafes,categories: currentState.categories));

      try {
        await toggleWishlist(event.cafeId, event.userCode);
      } catch (e) {
        // Revert on error
        emit(CafeLoaded(cafes: currentState.cafes, categories: currentState.categories));
        emit(CafeError(message: e.toString()));
      }
    } else if (currentState is CafeWishlistLoaded) {
      // Optimistic UI update for wishlist (remove item)
      final updatedWishlist = currentState.wishlist
          .where((cafe) => cafe.cafeId != event.cafeId)
          .toList();

      emit(CafeWishlistLoaded(wishlist: updatedWishlist));

      try {
        await toggleWishlist(event.cafeId, event.userCode);
      } catch (e) {
        // Revert on error
        emit(CafeWishlistLoaded(wishlist: currentState.wishlist));
        emit(CafeError(message: e.toString()));
      }
    }
  }

  Future<void> _onSearchCafes(
    SearchCafesEvent event,
    Emitter<CafeState> emit,
  ) async {
    emit(CafeLoading());
    try {
      final cafes = await searchCafes(event.keyword);
      
      // Dynamic category selection
      final dynamicCategories = cafes
          .map((c) => c.venueType)
          .where((t) => t.trim().isNotEmpty)
          .toSet()
          .toList();
      
      final finalCategories = ['All', ...dynamicCategories];
      
      emit(CafeLoaded(cafes: cafes, categories: finalCategories));
    } catch (e) {
      emit(CafeError(message: e.toString()));
    }
  }
}

import 'dart:convert';
import 'package:dio/dio.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:zinko_app/widgets/global_network_overlay.dart';
import 'package:zinko_app/features/auth/presentation/pages/login_screen.dart';
import 'package:zinko_app/features/auth/data/models/auth_responses.dart';
import 'package:zinko_app/features/auth/data/datasources/auth_local_data_source.dart';

class AuthInterceptor extends Interceptor {
  final SharedPreferences sharedPreferences;

  AuthInterceptor(this.sharedPreferences);

  @override
  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
    // 1. Centralized Token Addition
    final jsonString = sharedPreferences.getString(CACHED_USER_DATA);
    if (jsonString != null) {
      try {
        final userData = UserData.fromJson(json.decode(jsonString));
        if (userData.token.isNotEmpty) {
          final cleanToken = userData.token.trim().replaceAll('"', '');
          options.headers['Authentication'] = cleanToken;
        }
      } catch (_) {
        // Handle malformed JSON if necessary
      }
    }
    super.onRequest(options, handler);
  }

  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    // 2. Global Token Expiration/Unauthorized Handling (401 or 403)
    if (err.response?.statusCode == 401 || err.response?.statusCode == 403) {
      // Clear session cache
      sharedPreferences.clear();

      // Navigate to login screen and clear history
      // Note: pushing to the route automatically clears the stack
      zinkoNavigatorKey.currentState?.pushNamedAndRemoveUntil(
        LoginScreen.routeName,
        (route) => false,
      );
    }
    super.onError(err, handler);
  }
}

import 'dart:ui';

import 'package:flutter/material.dart';
import 'package:zinko_app/core/theme/app_colors.dart';
import 'package:zinko_app/core/theme/optimized_colors.dart';

class ZinkoBackground extends StatelessWidget {
  final Widget? child;
  final bool showOverlay;
  final ImageProvider<Object>? image;
  final Color? backgroundColor;

  const ZinkoBackground({
    super.key,
    this.child,
    this.showOverlay = true,
    this.image,
    this.backgroundColor,
  });

  @override
  Widget build(BuildContext context) {
    final screenSize = MediaQuery.sizeOf(context);

    return Stack(
      clipBehavior: Clip.none,
      children: [
        // Static Background Layer - uses physical screen size to ignore keyboard resizing
        Positioned(
          top: 0,
          left: 0,
          width: screenSize.width,
          height: screenSize.height,
          child: Container(
            decoration: BoxDecoration(
              color: backgroundColor ?? AppColors.backgroundDark,
              image: DecorationImage(
                image: image ??
                    const AssetImage('assets/images/dark_theme_bg.png'),
                fit: BoxFit.cover,
                alignment: Alignment.topCenter,
              ),
            ),
            child: ClipRect(
              child: BackdropFilter(
                filter: ImageFilter.blur(sigmaX: 5, sigmaY: 5),
                child: Container(
                  color: showOverlay
                      ? OptimizedColors.backgroundDark70
                      : Colors.transparent,
                ),
              ),
            ),
          ),
        ),
        // Content Layer
        if (child != null) child!,
      ],
    );
  }
}

