class WishlistScreen extends StatefulWidget {
  static const String routeName = '/wishlist';
  const WishlistScreen({super.key});

  @override
  State<WishlistScreen> createState() => _WishlistScreenState();
}

class _WishlistScreenState extends State<WishlistScreen> {
  @override
  void initState() {
    super.initState();
    final userState = context.read<UserBloc>().state;
    if (userState is UserLoaded) {
      context.read<CafeBloc>().add(GetWishlistEvent(userCode: userState.user.userCode));
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      extendBodyBehindAppBar: true,
      appBar: AppBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        leading: Padding(
          padding: const EdgeInsets.all(8.0),
          child: _GlassHeaderButton(
            icon: Icons.arrow_back_ios_new_rounded,
            onTap: () => Navigator.pop(context),
          ),
        ),
        title: Text(
          'WISHLIST',
          style: TextStyle(
            color: GlassTheme.textColor(context),
            fontWeight: FontWeight.w900,
            fontSize: 15,
            letterSpacing: 1.5,
          ),
        ),
        centerTitle: true,
      ),
      body: ZinkoBackground(
        child: SafeArea(
          child: BlocBuilder<CafeBloc, CafeState>(
            builder: (context, state) {
              if (state is CafeLoading) {
                return _buildLoadingState(context);
              }
              if (state is CafeWishlistLoaded) {
                final favorites = state.wishlist;
                if (favorites.isEmpty) return _buildEmptyState(context);
                return ListView.builder(
                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 100),
                  physics: const BouncingScrollPhysics(),
                  itemCount: favorites.length,
                  itemBuilder: (context, index) {
                    final cafe = favorites[index];
                    final workspace = CafeMapper.toWorkspaceEntity(cafe);
                    return GestureDetector(
                      onTap: () {
                        // Proactively fetch latest details for this workspace
                        context.read<WorkspaceBloc>().add(GetWorkspacesEvent());
                        
                        Navigator.pushNamed(
                            context, WorkspaceDetailScreen.routeName,
                            arguments: workspace);
                      },
                      child: _WishlistCard(
                        workspace: workspace,
                        onRemove: () {
                          final userState = context.read<UserBloc>().state;
                          if (userState is UserLoaded) {
                            context.read<CafeBloc>().add(ToggleWishlistEvent(
                                  cafeId: cafe.cafeId,
                                  userCode: userState.user.userCode,
                                ));
                          }
                        },
                      ).animate().fadeIn(delay: (index * 80).ms),
                    );
                  },
                );
              }
              if (state is CafeError) {
                return Center(
                    child: Text(state.message,
                        style:
                            TextStyle(color: GlassTheme.textColor(context))));
              }
              return const SizedBox.shrink();
            },
          ),
        ),
      ),
    );
  }

  Widget _buildLoadingState(BuildContext context) {
    return ListView.builder(
      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 8),
      itemCount: 5,
      itemBuilder: (context, index) => Padding(
        padding: const EdgeInsets.only(bottom: 16),
        child: AutoSkeleton(
          show: true,
          child: Container(
            height: 120,
            decoration: BoxDecoration(
              color: GlassTheme.glassColor(context),
              borderRadius: BorderRadius.circular(20),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildEmptyState(BuildContext context) {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Icon(Icons.favorite_rounded,
              size: 56, color: OptimizedColors.white10),
          const SizedBox(height: 12),
          const Text(
            'EMPTY WISHLIST',
            style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w900,
                color: OptimizedColors.white50,
                letterSpacing: 1.5),
          ),
          const SizedBox(height: 6),
          const Text(
            'Your favorite spaces will appear here',
            textAlign: TextAlign.center,
            style: TextStyle(
                fontSize: 13,
                color: OptimizedColors.white50,
                fontWeight: FontWeight.w500),
          ),
          const SizedBox(height: 24),
          GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
              decoration: BoxDecoration(
                color: AppColors.primary,
                borderRadius: BorderRadius.circular(16),
                boxShadow: [
                  BoxShadow(
                    color: AppColors.primary.withValues(alpha: 0.3),
                    blurRadius: 15,
                    offset: const Offset(0, 5),
                  )
                ],
              ),
              child: const Text(
                'EXPLORE SPACES',
                style: TextStyle(
                    fontWeight: FontWeight.w900,
                    fontSize: 13,
                    color: AppColors.white,
                    letterSpacing: 0.5),
              ),
            ),
          ).animate().scale(),
        ],
      ),
    );
  }
}

